(function() {
    'use strict';

    class ParrillaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Restaurante que No Para';
            this.version = '1.1.0';
            this._tableListenersAttached = false;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    operatingMargin: 8.2,
                    nps: 28,
                    tableUtilization: 72,
                    waiterTurnover: 64,
                    avgWaitTime: 18,
                    budget: 2000000,
                    marginHistory: [],
                    npsHistory: [],
                    utilizationHistory: [],
                    waitTimeHistory: [],
                    turnoverHistory: [],
                    communalActive: false,
                    digitalReservation: false,
                    staffInvested: 'none',
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    twoPct: 20,
                    fourPct: 40,
                    sixPct: 30,
                    communalPct: 10,
                    kitchenFix: 'addStaff',
                    waiterTables: 6,
                    reservationSystem: 'manual',
                    communalExperience: 'skip',
                    staffInvestment: 'none',
                    yieldManagement: 'fixed',
                    queueManagement: 'none'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var currentState = window.mySimulation.state;
            var round = currentState.currentPeriod;
            this._updateBriefing(currentState);

            if (round === 1) {
                var twoPct = parseInt(document.getElementById('twoPctInput').value) || 0;
                var fourPct = parseInt(document.getElementById('fourPctInput').value) || 0;
                var sixPct = parseInt(document.getElementById('sixPctInput').value) || 0;
                var communalPct = parseInt(document.getElementById('communalPctInput').value) || 0;
                var total = twoPct + fourPct + sixPct + communalPct;

                if (total !== 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('table_total_warning'), 'warning'
                    );
                    return false;
                }

                decisions.twoPct = twoPct;
                decisions.fourPct = fourPct;
                decisions.sixPct = sixPct;
                decisions.communalPct = communalPct;
                decisions.kitchenFix = document.getElementById('kitchenFixInput').value;
                decisions.waiterTables = parseInt(document.getElementById('waiterTablesInput').value);
                decisions.reservationSystem = document.getElementById('reservationInput').value;

            } else if (round === 2) {
                decisions.communalExperience = document.getElementById('communalExpInput').value;
                decisions.staffInvestment = document.getElementById('staffInvestInput').value;

            } else if (round === 3) {
                decisions.yieldManagement = document.getElementById('yieldInput').value;
                decisions.queueManagement = document.getElementById('queueInput').value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var marginDelta = 0;
            var npsDelta = 0;
            var utilDelta = 0;
            var turnoverDelta = 0;
            var waitDelta = 0;
            var investmentCost = 0;
            var eventMessage = '';

            if (round === 1) {
                // Table configuration: match score against demand distribution
                // Demand: 25% couples, 35% groups of 4, 25% groups of 6, 15% large/communal
                var mismatch = Math.abs(d.twoPct - 25) + Math.abs(d.fourPct - 35) + Math.abs(d.sixPct - 25) + Math.abs(d.communalPct - 15);
                var matchScore = 100 - (mismatch / 2);
                utilDelta += (matchScore - 50) * 0.24;

                // Kitchen bottleneck fix (VUT equation application)
                if (d.kitchenFix === 'addStaff') {
                    // Add parrillero: utilization drops 88%->80%, CTq drops ~61%
                    waitDelta = -11;
                    investmentCost += 180000;
                } else if (d.kitchenFix === 'menuRedesign') {
                    // Reduce Cs from 0.65 to 0.40, moderate wait improvement
                    waitDelta = -6;
                    investmentCost += 150000;
                } else if (d.kitchenFix === 'both') {
                    // Maximum improvement
                    waitDelta = -13;
                    investmentCost += 330000;
                }

                // Waiter table assignment (Service-Profit Chain)
                if (d.waiterTables === 4) {
                    turnoverDelta = -26;
                    npsDelta += 12;
                    marginDelta -= 1.5;
                } else if (d.waiterTables === 5) {
                    turnoverDelta = -15;
                    npsDelta += 6;
                    marginDelta -= 0.7;
                }
                // 6 tables = current state, no change

                // Reservation system upgrade
                if (d.reservationSystem === 'digital') {
                    utilDelta += 5;
                    npsDelta += 3;
                    investmentCost += 292000;
                    ds.digitalReservation = true;
                }

                // Derived margin effects from operational improvements
                marginDelta += utilDelta * 0.12;
                marginDelta += Math.max(0, -waitDelta) * 0.08;

                // Random event: health inspection (30% probability)
                if (Math.random() < 0.30) {
                    investmentCost += 120000;
                    marginDelta -= 0.5;
                    eventMessage = window.mySimulation.t('event_health_inspection');
                }

            } else if (round === 2) {
                // Communal parrillada experience (batching insight)
                if (d.communalExperience === 'fullInvest') {
                    utilDelta = 8;
                    npsDelta += 10;
                    marginDelta += 3.5;
                    investmentCost += 840000;
                    ds.communalActive = true;
                } else if (d.communalExperience === 'pilot') {
                    utilDelta = 4;
                    npsDelta += 5;
                    marginDelta += 1.5;
                    investmentCost += 320000;
                    ds.communalActive = true;
                }

                // Employee satisfaction program (Service-Profit Chain investment)
                if (d.staffInvestment === 'full') {
                    turnoverDelta = -25;
                    npsDelta += 15;
                    marginDelta -= 2.0;
                    ds.staffInvested = 'full';
                } else if (d.staffInvestment === 'incremental') {
                    turnoverDelta = -12;
                    npsDelta += 7;
                    marginDelta -= 0.8;
                    ds.staffInvested = 'incremental';
                }

                // Derived margin from NPS/loyalty improvement
                marginDelta += npsDelta * 0.06;

                // Random event: TripAdvisor review bomb (25%)
                if (Math.random() < 0.25) {
                    npsDelta -= 8;
                    eventMessage = window.mySimulation.t('event_tripadvisor');
                }

                // Random event: head parrillero resigns (20%)
                if (Math.random() < 0.20) {
                    waitDelta += 5;
                    if (eventMessage) {
                        eventMessage += '<br>' + window.mySimulation.t('event_parrillero_quits');
                    } else {
                        eventMessage = window.mySimulation.t('event_parrillero_quits');
                    }
                }

            } else if (round === 3) {
                // Carnaval peak: 340% demand surge
                utilDelta += 12;

                // Yield management strategy
                if (d.yieldManagement === 'premium') {
                    marginDelta += 4.0;
                    npsDelta -= 5;
                } else if (d.yieldManagement === 'surge') {
                    marginDelta += 2.5;
                    npsDelta -= 2;
                } else {
                    // Fixed pricing builds loyalty
                    npsDelta += 3;
                }

                // Queue management
                if (d.queueManagement === 'barWhatsapp') {
                    npsDelta += 8;
                    utilDelta += 5;
                    marginDelta += 1.0;
                    investmentCost += 85000;
                } else if (d.queueManagement === 'manual') {
                    npsDelta += 3;
                    utilDelta += 2;
                } else {
                    // No queue system during Carnaval = chaos
                    npsDelta -= 8;
                }

                // Long-term Service-Profit Chain payoff
                if (ds.staffInvested === 'full') {
                    npsDelta += 5;
                    marginDelta += 1.2;
                } else if (ds.staffInvested === 'incremental') {
                    npsDelta += 2;
                    marginDelta += 0.5;
                }

                // Communal experience ongoing revenue benefit
                if (ds.communalActive) {
                    marginDelta += 1.5;
                    npsDelta += 3;
                }

                // Digital reservation handles peak demand better
                if (ds.digitalReservation) {
                    utilDelta += 3;
                    npsDelta += 2;
                }

                // Random event: new competitor opens (40%)
                if (Math.random() < 0.40) {
                    npsDelta -= 5;
                    utilDelta -= 3;
                    eventMessage = window.mySimulation.t('event_competitor');
                }
            }

            // Apply investment cost to budget
            ds.budget -= investmentCost;

            // Over-budget penalty
            if (ds.budget < 0) {
                marginDelta -= 1.5;
                npsDelta -= 3;
            }

            // Apply all deltas with clamping
            ds.operatingMargin = Math.round((ds.operatingMargin + marginDelta) * 10) / 10;
            ds.operatingMargin = Math.max(0, Math.min(30, ds.operatingMargin));

            ds.nps = Math.round(ds.nps + npsDelta);
            ds.nps = Math.max(-100, Math.min(100, ds.nps));

            ds.tableUtilization = Math.round((ds.tableUtilization + utilDelta) * 10) / 10;
            ds.tableUtilization = Math.max(0, Math.min(100, ds.tableUtilization));

            ds.waiterTurnover = Math.round((ds.waiterTurnover + turnoverDelta) * 10) / 10;
            ds.waiterTurnover = Math.max(5, Math.min(100, ds.waiterTurnover));

            ds.avgWaitTime = Math.round((ds.avgWaitTime + waitDelta) * 10) / 10;
            ds.avgWaitTime = Math.max(2, Math.min(30, ds.avgWaitTime));

            ds.eventLog = eventMessage;

            // Push to history arrays for charts
            ds.marginHistory.push(ds.operatingMargin);
            ds.npsHistory.push(ds.nps);
            ds.utilizationHistory.push(ds.tableUtilization);
            ds.waitTimeHistory.push(ds.avgWaitTime);
            ds.turnoverHistory.push(ds.waiterTurnover);

            // Show/hide event panel
            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventMessage && eventPanel && eventText) {
                eventPanel.style.display = 'block';
                eventText.innerHTML = eventMessage;
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }

            // v1.1.0 P0 FIX: render next round's controls synchronously.
            // Old setTimeout fired AFTER the framework incremented state.currentPeriod, so
            // (currentPeriod + 1) overshot by one and showed the wrong round's control panel
            // (round N+2) for rounds 2+. Called here pre-increment, currentPeriod is still N,
            // so (N + 1) correctly targets the next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });

            return {
                period: state.currentPeriod,
                operatingMargin: ds.operatingMargin,
                nps: ds.nps,
                tableUtilization: ds.tableUtilization,
                waiterTurnover: ds.waiterTurnover,
                avgWaitTime: ds.avgWaitTime,
                budget: ds.budget,
                investmentCost: investmentCost,
                eventMessage: eventMessage
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                function(v) { return 'ARS ' + Math.round(v).toLocaleString(); });
            uiManager.bind('marginDisplay', 'domainState.operatingMargin',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('npsDisplay', 'domainState.nps',
                function(v) { return (v >= 0 ? '+' : '') + v; });
            uiManager.bind('utilDisplay', 'domainState.tableUtilization',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('turnoverDisplay', 'domainState.waiterTurnover',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('waitDisplay', 'domainState.avgWaitTime',
                function(v) { return v.toFixed(1) + ' min'; });

            // v1.1.0 FIX: framework Undo restores state/KPIs but not this sim's control panels.
            // Re-render the restored round's controls (deferred, after the framework undo handler).
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation && window.mySimulation.state) {
                            self._updateBriefing(window.mySimulation.state);
                        }
                    }, 0);
                });
            }
        }

        getChartConfig() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_margin_series'),
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y'
                        }, {
                            label: t('chart_nps_series'),
                            data: [],
                            borderColor: '#2980b9',
                            backgroundColor: 'rgba(41,128,185,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_fin_title') }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                position: 'left',
                                title: { display: true, text: t('chart_axis_margin') }
                            },
                            y1: {
                                position: 'right',
                                title: { display: true, text: t('chart_axis_nps') },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                },
                operationsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_util_series'),
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y'
                        }, {
                            label: t('chart_wait_series'),
                            data: [],
                            borderColor: '#8e44ad',
                            backgroundColor: 'rgba(142,68,173,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_ops_title') }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                position: 'left',
                                title: { display: true, text: t('chart_axis_util') }
                            },
                            y1: {
                                beginAtZero: true,
                                position: 'right',
                                title: { display: true, text: t('chart_axis_wait') },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.marginHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.marginHistory },
                        { data: state.domainState.npsHistory }
                    ]
                },
                operationsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.utilizationHistory },
                        { data: state.domainState.waitTimeHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var last = history[history.length - 1];
            var r = last.results || {};
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            // Weighted score based on concept KPI weights
            // Operating Margin target: 13% (from 8.2%) — weight 30%
            var marginScore = Math.min(100, Math.max(0, (r.operatingMargin - 8.2) / (13 - 8.2) * 100));
            // NPS target: +50 (from +28) — weight 25%
            var npsScore = Math.min(100, Math.max(0, (r.nps - 28) / (50 - 28) * 100));
            // Utilization target: 88% (from 72%) — weight 20%
            var utilScore = Math.min(100, Math.max(0, (r.tableUtilization - 72) / (88 - 72) * 100));
            // Turnover target: 40% (from 64%) — weight 15%
            var turnoverScore = Math.min(100, Math.max(0, (64 - r.waiterTurnover) / (64 - 40) * 100));
            // Wait time target: 10 min (from 18 min) — weight 10%
            var waitScore = Math.min(100, Math.max(0, (18 - r.avgWaitTime) / (18 - 10) * 100));

            var weighted = marginScore * 0.30 + npsScore * 0.25 + utilScore * 0.20 + turnoverScore * 0.15 + waitScore * 0.10;
            var totalScore = Math.round(weighted * 10);

            var performance = t('perf_needs');
            if (totalScore >= 700) {
                performance = t('perf_excellent');
            } else if (totalScore >= 500) {
                performance = t('perf_good');
            } else if (totalScore >= 300) {
                performance = t('perf_developing');
            }

            var insights = [];
            if (r.operatingMargin >= 13) {
                insights.push(t('insight_margin_high'));
            } else {
                insights.push(t('insight_margin_low'));
            }
            if (r.nps >= 50) {
                insights.push(t('insight_nps_high'));
            } else {
                insights.push(t('insight_nps_low'));
            }
            if (r.tableUtilization >= 88) {
                insights.push(t('insight_util_high'));
            }
            if (r.waiterTurnover <= 40) {
                insights.push(t('insight_turnover_low'));
            }
            if (r.avgWaitTime <= 10) {
                insights.push(t('insight_wait_low'));
            }

            return {
                totalScore: totalScore,
                performance: performance,
                operatingMargin: r.operatingMargin,
                nps: r.nps,
                tableUtilization: r.tableUtilization,
                waiterTurnover: r.waiterTurnover,
                avgWaitTime: r.avgWaitTime,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.operatingMargin < 8.2) return window.mySimulation.t('hint_margin_drop');
            if (results.nps < 20) return window.mySimulation.t('hint_nps_critical');
            if (results.avgWaitTime > 15) return window.mySimulation.t('hint_wait_high');
            if (state.domainState.budget < 0) return window.mySimulation.t('hint_over_budget');
            if (results.tableUtilization > 85) return window.mySimulation.t('hint_util_good');
            return null;
        }

